import json
import pandas as pd

# Load CSV
df = pd.read_csv(
    r"C:\Users\PERFECT SOLUTION\Downloads\conversation-routing-5223832f.csv"
)

# Extract route values from JSON strings
def get_expected_route(value):
    try:
        return json.loads(value).get("expected_route")
    except Exception:
        return None


def get_route(value):
    try:
        return json.loads(value).get("route")
    except Exception:
        return None


df["expected_route"] = df["reference_outputs"].apply(get_expected_route)
df["predicted_route"] = df["outputs"].apply(get_route)

# Filter mismatches
mismatched_df = df[df["expected_route"] != df["predicted_route"]]

print(f"Total mismatched questions: {len(mismatched_df)}")

if len(mismatched_df) > 0:
    print("\nMismatched rows:\n")
    print(
        mismatched_df[
            [
                "id",
                "expected_route",
                "predicted_route",
            ]
        ]
    )
else:
    print("\n?? All routes match!")
